use std::collections::BTreeMap;use artifactum_core::{provider_error,AcquireContext,AcquisitionPlan,ArtifactPath,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,ResolvedFile,ResolvedRevision,Resolution};use artifactum_provider_api::{header_token,plan,profile_value};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct DataverseProvider;
fn target<'a>(r:&'a ArtifactRequirement,c:&ResolveContext)->artifactum_core::Result<(String,&'a str)>{if let Some(base)=profile_value(c,"base_url"){return Ok((base.trim_end_matches('/').into(),r.reference.locator()))}let(base,id)=r.reference.locator().split_once('#').ok_or_else(||provider_error("dataverse","without a profile use dataverse:<https://host>#<file-id>"))?;Ok((base.trim_end_matches('/').into(),id))}
#[async_trait]impl ArtifactProvider for DataverseProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"dataverse".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["dataverse".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,auth:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,c:&ResolveContext)->artifactum_core::Result<Resolution>{let(base,id)=target(r,c)?;let mut url=format!("{base}/api/access/datafile/{id}");if profile_value(c,"original")==Some("true"){url.push_str("?format=original");}let headers=header_token(c.profile.as_ref(),"token_env","DATAVERSE_API_TOKEN","X-Dataverse-key");let name=format!("datafile-{id}");let rf=ResolvedFile{path:ArtifactPath::new(&name)?,size:None,digests:Default::default(),media_type:None,source:serde_json::json!({"url":url})};Ok(Resolution{provider:"dataverse".into(),canonical_ref:r.reference.to_string(),revision:r.revision.as_ref().map(|id|ResolvedRevision{id:id.clone(),requested:Some(id.clone())}),files:vec![rf],provider_state:serde_json::Value::Null,metadata:BTreeMap::new()})}async fn prepare_acquisition(&self,f:&ResolvedFile,c:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{let url=f.source.get("url").and_then(|v|v.as_str()).ok_or_else(||provider_error("dataverse","missing access URL"))?;let headers=header_token(c.profile.as_ref(),"token_env","DATAVERSE_API_TOKEN","X-Dataverse-key");Ok(plan(url,headers))}}
pub fn provider()->DataverseProvider{DataverseProvider}
